window.docContents[228].resolve({"/Preface/#Logical-Foundations--Preface--Practicalities--Downloading-the-Rocq-Files":{"contents":"A tar file containing the full sources for the \"release version\"\nof this book (as a collection of Rocq scripts and HTML files) is\navailable at <https://softwarefoundations.cis.upenn.edu>.\n\nIf you are using the book as part of a class, your professor may\ngive you access to a locally modified version of the files; you\nshould use that one instead of the public release version, so that\nyou get any local updates during the semester.\n\n","context":"Logical Foundations\u0009Preface\u0009Practicalities","header":"1.3.4. Downloading the Rocq Files","id":"/Preface/#Logical-Foundations--Preface--Practicalities--Downloading-the-Rocq-Files"}});